// Construct a concrete ILuaModuleManager10 without using FUZZ_PARAM inside class scope.
// All fuzz-derived data is gathered here and passed into the object to avoid capture issues.

class FakeLuaModuleManager10 : public ILuaModuleManager10 {
public:
    struct ResRec { std::string name; lua_State* vm; };
    struct RegRec { lua_State* vm; std::string name; lua_CFunction func; };

    std::vector<ResRec> resources;
    std::vector<RegRec> registry;

    unsigned long ver_ul;
    unsigned long net_ul;
    std::string ver_str;
    std::string ver_name;
    std::string os_name;

    FakeLuaModuleManager10(const std::vector<ResRec>& res,
                           unsigned long ver,
                           unsigned long net,
                           const std::string& verStr,
                           const std::string& verName,
                           const std::string& os)
        : resources(res), ver_ul(ver), net_ul(net), ver_str(verStr), ver_name(verName), os_name(os) {}

    // ILuaModuleManager methods
    virtual void ErrorPrintf(const char* /*szFormat*/, ...) {}
    virtual void DebugPrintf(lua_State* /*luaVM*/, const char* /*szFormat*/, ...) {}
    virtual void Printf(const char* /*szFormat*/, ...) {}

    virtual bool RegisterFunction(lua_State* luaVM, const char* szFunctionName, lua_CFunction Func) {
        if (!luaVM || !szFunctionName || !Func) return false;
        std::string name(szFunctionName);
        if (name.empty()) return false;
        if (name.size() > 64) name.resize(64);
        registry.push_back({luaVM, name, Func});
        return true;
    }

    virtual bool GetResourceName(lua_State* luaVM, std::string& strName) {
        if (!luaVM) return false;
        for (auto& r : resources) { if (r.vm == luaVM) { strName = r.name; return true; } }
        return false;
    }

    virtual CChecksum GetResourceMetaChecksum(lua_State* luaVM) {
        CChecksum cs{};
        std::string name;
        if (!luaVM || !GetResourceName(luaVM, name)) { cs.ulCRC = 0; for (int i=0;i<16;++i) cs.mD5[i]=0; return cs; }
        fillChecksumFromKey(name, cs);
        return cs;
    }

    virtual CChecksum GetResourceFileChecksum(lua_State* luaVM, const char* szFile) {
        CChecksum cs{};
        std::string name;
        if (!luaVM || !szFile || !GetResourceName(luaVM, name)) { cs.ulCRC = 0; for (int i=0;i<16;++i) cs.mD5[i]=0; return cs; }
        std::string key = name + std::string(":") + std::string(szFile);
        fillChecksumFromKey(key, cs);
        return cs;
    }

    // ILuaModuleManager10 methods
    virtual unsigned long GetVersion() { return ver_ul; }
    virtual const char* GetVersionString() { return ver_str.c_str(); }
    virtual const char* GetVersionName() { return ver_name.c_str(); }
    virtual unsigned long GetNetcodeVersion() { return net_ul; }
    virtual const char* GetOperatingSystemName() { return os_name.c_str(); }

    virtual lua_State* GetResourceFromName(const char* szResourceName) {
        if (!szResourceName) return nullptr;
        std::string q(szResourceName);
        for (auto& r : resources) { if (r.name == q) return r.vm; }
        for (auto& r : resources) { if (r.name.find(q) != std::string::npos) return r.vm; }
        return nullptr;
    }

    virtual bool GetResourceName(lua_State* luaVM, char* szName, size_t length) {
        if (!luaVM || !szName || length == 0) return false;
        std::string out;
        if (!GetResourceName(luaVM, out)) return false;
        size_t toCopy = (out.size() < (length - 1)) ? out.size() : (length - 1);
        for (size_t i = 0; i < toCopy; ++i) szName[i] = out[i];
        szName[toCopy] = '\0';
        return true;
    }

    virtual bool GetResourceFilePath(lua_State* luaVM, const char* fileName, char* path, size_t length) {
        if (!luaVM || !fileName || !path || length == 0) return false;
        std::string res;
        if (!GetResourceName(luaVM, res)) return false;
        std::string full = std::string("resources/") + res + std::string("/") + std::string(fileName);
        size_t toCopy = (full.size() < (length - 1)) ? full.size() : (length - 1);
        for (size_t i = 0; i < toCopy; ++i) path[i] = full[i];
        path[toCopy] = '\0';
        return true;
    }

private:
    void fillChecksumFromKey(const std::string& key, CChecksum& out) {
        // Simple FNV-1a style mix to produce deterministic data
        unsigned long crc = 0x811C9DC5u;
        for (unsigned char c : key) crc = (crc ^ c) * 16777619u;
        out.ulCRC = crc;
        for (int i = 0; i < 16; ++i) {
            unsigned char b = (unsigned char)((crc >> ((i % 4) * 8)) & 0xFFu);
            if (!key.empty()) b ^= (unsigned char)key[i % key.size()];
            out.mD5[i] = b;
        }
    }
};

