res.reserve(count);
for (unsigned int i = 0; i < count; ++i) {
    std::string base = FUZZ_PARAM_STR();
    if (base.empty()) base = "res";
    if (base.size() > 32) base.resize(32);
    std::string name = base + std::string("_") + std::to_string(i);
    // Create an opaque lua_State* by allocating a small blob; not freed here to keep VM valid across pool usage
    char* slot = new char[16];
    for (int k = 0; k < 16; ++k) slot[k] = (char)(0xA0 + ((i + k) & 0x0F));
    lua_State* vm = reinterpret_cast<lua_State*>(slot);
    res.push_back({name, vm});
}

